INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-001', 'Ledger guard reported every feature as test-less and blocked the first commit', 'test collector passed -q on top of the project addopts -q; pytest -qq prints ''file: count'' instead of node ids', 'fixed', 'tests/gates/test_ledger_hooks.py::test_test_collector_returns_node_ids_whatever_the_pytest_addopts', 'C-20261112-0001');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-002', 'Regression-test guard accepted a test outside tests/unit, which never runs on a commit', 'guard checked existence anywhere under tests/; hooks and CI run tests/unit only', 'fixed', 'tests/gates/test_ledger.py::test_regression_test_outside_the_unit_job_does_not_count', 'C-20261112-0002');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-003', 'CI stage compared HEAD with itself, so lost features and missing change rows were never caught past the hooks', '--stage ci read both sides from HEAD:', 'fixed', 'tests/gates/test_ledger_hooks.py::test_ci_stage_compares_the_last_commit_with_its_parent', 'C-20261112-0002');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-004', 'Change-Author trailer was not compared with the change row''s author', 'commit-msg only checked the trailer existed', 'fixed', 'tests/gates/test_ledger.py::test_author_trailer_must_match_the_new_change_row', 'C-20261112-0002');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-005', 'ledger CLI wrote to <cwd>/ledgers, the wrong place from a subdirectory', 'Path.cwd() instead of the git top level', 'fixed', 'tests/gates/test_ledger_hooks.py::test_ledger_cli_writes_to_the_repo_ledger_from_a_subdirectory', 'C-20261112-0002');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-006', 'Git hook environment (GIT_DIR/GIT_INDEX_FILE) leaked into the ledger tools and the hook tests: under pre-commit, a test''s temp-repo ''git init/commit'' acted on the real repo — it committed an emptied tree onto the graph-schema branch and turned the main checkout bare', 'subprocess git calls inherited git''s hook variables instead of resolving the repo from the working directory', 'fixed', 'tests/gates/test_ledger_hooks.py::test_ledger_cli_resolves_the_repo_from_cwd_not_from_git_dir', 'C-20261112-0005');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-007', 'CI ledger guard loaded an EMPTY ledger when git history was unreadable (act copies files without history), then crashed with ''no such table'' instead of saying why', '_ledger_at() treated a failed `git show` as empty content', 'fixed', 'tests/gates/test_ledger.py::test_loading_the_ledger_from_an_unreadable_git_revision_fails_loudly', 'C-20261112-0007');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-graph-schema-001', 'Old graph stored domain/entity_type/artifact_type/artifact_id three times (flat, md_*, JSON); readers coalesced between drifting copies (old BL-11)', 'no schema check; storage wrote copies', 'open', NULL, NULL);
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-graph-schema-002', 'Unlabeled community match scanned 1,037,406 db hits (416 ms) for 10 rows; no index on community id (old BL-39)', 'MATCH (c {id:$id}) without a label; index missing', 'open', NULL, NULL);
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-graph-schema-003', 'A reverted SUPERSEDES edge still hid its target: readers matched the bare pattern and ignored r.status (old project_unifile:4347)', 'readers did not filter SUPERSEDES.status', 'open', NULL, NULL);
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-008', 'The review gate could never pass: it looked for reviews/<HEAD>.md, but committing the review file moves HEAD, so the head was always one commit past the reviewed one (found merging graph-schema 3df1363)', 'review_gate.main used HEAD as the reviewed commit; a review records the tree of the commit it names, and recording it is itself a commit', 'fixed', 'tests/gates/test_review_gate.py::test_a_review_only_head_is_judged_by_its_parents_review', 'C-20261112-0010');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-009', 'An appended UPDATE / INSERT OR REPLACE / upsert line in a ledger row file rewrote an earlier row (e.g. a change summary) while every guard stayed green (found by review 59a67c1)', 'tools.ledger.load ran each row file with executescript; the guards loaded through their own executescript (check_ledgers._ledger_at), and compared change-row ids, not contents. The first fix (c4bda9c) still let a REPLACE follow a valid insert on one line and left the guards on the old loader (review c4bda9c BLOCKING 1-2)', 'fixed', 'tests/gates/test_ledger.py::test_a_ledger_line_that_rewrites_an_earlier_row_is_rejected', 'C-20261112-0015');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-010', 'A protected check file could change without CHECK-CHANGE or the owner line: renamed away (git reported only the new path), named with a tab, quote or non-ASCII byte (git quoted the path), or given as the bare directory path', 'diff --name-only without --no-renames and -z; the protected match required the trailing slash', 'fixed', 'tests/gates/test_gate_attacks.py::test_r3_commit_msg_stage_sees_every_touch', 'C-20261112-0016');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-011', 'The review gate let MERGE: yes pass with a BLOCKING finding in a bullet, quote, heading, task box, table cell or tag; with a missing/deferred status in bold, code or a row without outer pipes; with an empty deferred reason; with a drift heading inside prose, a code fence or a comment; and with MERGE: no beside MERGE: yes', 'line-start-only regex for BLOCKING; table rows required both outer pipes; structure was read from raw text including code and comments', 'fixed', 'tests/gates/test_gate_attacks.py::test_r4_blocking_finding_in_any_markdown_form_refuses', 'C-20261112-0016');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-012', 'A review-record head could carry other changes and still be judged by its parent''s review: a file renamed into reviews/, a mode change, a change row inserted mid-file or prepended', 'the record check used --name-only (renames, modes invisible) and numstat deletions = 0 (a mid-file insert has none)', 'fixed', 'tests/gates/test_gate_attacks.py::test_r4_any_other_head_is_judged_as_itself', 'C-20261112-0016');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-013', 'CI audited the ledger of the last commit only and never ran the lost-feature check, so a --no-verify commit mid-branch could rewrite a change row, delete a bug or drop a feature unseen (review d969d76)', 'the ci stage compared HEAD with HEAD~1 only; lost_features ran only at commit-msg', 'fixed', 'tests/gates/test_gate_attacks_round2.py::test_r6_one_bad_commit_anywhere_fails_ci', 'C-20261112-0017');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-014', 'Gate settings could be overridden without touching a protected file: ruff.toml, mypy.ini, .coveragerc, pytest.ini, .importlinter, setup.cfg, tox.ini, any conftest.py, tools/__init__.py (review d969d76)', 'the protected set listed pyproject.toml but not the files that take precedence over it', 'fixed', 'tests/gates/test_gate_attacks_round2.py::test_r7_gate_config_needs_both_approval_lines', 'C-20261112-0017');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-015', 'ledger.insert wrote values with \\r, \\v, \\f, \\x1c-\\x1e, \\x85, U+2028/2029 raw and the strict loader then refused the whole ledger (regression from d969d76, review d969d76)', 'the loader split lines with str.splitlines(), insert flattened only \\n', 'fixed', 'tests/gates/test_gate_attacks_round2.py::test_r8_line_breaks_load_as_single_spaces', 'C-20261112-0017');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-016', 'The test step can report green without running any test: a root pytest.py shadows pytest (python -m puts the working directory first on sys.path), or a test module calls os._exit(0) at import; collect-only still works, so the ledger guard stays green (review 42ff52d, pre-existing on main)', 'gates run python without safe-path mode, and CI does not check that the executed tests equal the collected ones', 'fixed', 'tests/gates/test_infra_round1_qa.py::test_r1_atexit_exit_cannot_hide_a_failure_from_ci', 'C-20261113-0001');
INSERT INTO bug (id, description, root_cause, status) VALUES ('B-foundation-017', 'Gate config files are protected only at the repo root: a nested ruff.toml, .ruff.toml or pyproject.toml anywhere, or tests/pytest.ini, passes check_change_problems; a nested src/pkg/ruff.toml with select=["E9"] cut ruff from 6 findings to 1 (hid S602 shell=True and eval), and tests/pytest.ini overrides the root pytest config for CI (QA Q10, Claude/qa-0c6d89f2, 2026-11-13)', 'tools/ci/protected.txt lists those config names as root paths, not as **/ patterns (same class as B-foundation-014)', 'open');
INSERT INTO bug (id, description, root_cause, status) VALUES ('B-foundation-018', 'Test code can forge the junit report the CI test step trusts: a fixture reads request.config.option.xmlpath and an atexit handler strips <failure>, sets failures="0" and calls os._exit(0); pytest printed "1 failed, 1 passed" yet tools/ci/pytest_gate.py printed all executed and passed with exit 0 (QA Q11, Claude/qa-0c6d89f2, 2026-11-13, verified end to end)', 'the gate trusts a report file that the code under test can locate and rewrite after the run; nothing cross-checks it against pytest''s own terminal summary', 'open');
INSERT INTO bug (id, description, root_cause, status) VALUES ('B-foundation-019', 'The ledger guard and the review gate run as python -m without safe-path mode, so a repo-root module named like a stdlib module they import after start-up (e.g. subprocess.py) shadows it and can fake a green gate: .github/workflows/ci.yml:35, :41 (check_ledgers --stage ci / commit-msg), :44 (review_gate), .githooks/pre-commit:13 and .githooks/commit-msg:5 (check_ledgers); same root cause as B-foundation-016, applied to the gate processes (VP R&D review of the B-016 diff, 2026-11-13)', 'python -m puts the working directory first on sys.path; these gates import tools.* so they cannot simply run with -P, and -P with the repo root re-added brings the shadow back', 'open');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-020', 'An installed wheel could not find its configuration: memini.infra.paths resolved config/ as parents[3] of its own file (paths.py:13), which is the repo in a checkout but site-packages/../config in an installed package, and the wheel shipped only src/memini, so graph_schema.yaml and the prompts were missing (wheel listing 2026-11-14: memini/*.py + dist-info only; review b0bacbd NOTE, T-027)', 'config/ lived outside the package and was not included in the wheel; the path was computed from the source layout', 'fixed', 'tests/gates/test_wheel_install.py::test_installed_schema_loads_and_validates', 'C-20261114-0011');
INSERT INTO bug (id, description, root_cause, status, regression_test, fixed_in) VALUES ('B-foundation-021', 'CI failed on the public repository''s first push (77bce1f, a single root commit): the ledger guard compared HEAD with HEAD~1 and stopped with "cannot read ledgers/schema.sql at ''HEAD~1:''"; the commit-message audit checked 0 commits on every push to main (merge-base(main, HEAD) = HEAD) and on pull requests audited GitHub''s synthetic merge commit', 'the ci stage assumed every commit has a parent and derived the audit range from a local main branch instead of the GitHub event', 'fixed', 'tests/gates/test_ci_audit_range.py::test_root_commit_with_exactly_one_change_row_passes', 'C-20261114-0002');
